function field(f,value){const v=value??f.value??'',full=f.full?' full':'';if(f.type==='section')return `<div class="form-section">${esc(f.label)}</div>`;if(f.type==='checkbox')return `<label class="check-label${full}"><input type="checkbox" name="${f.key}" ${v?'checked':''}>${esc(f.label)}</label>`;let control;if(f.type==='textarea')control=`<textarea id="f-${f.key}" name="${f.key}" maxlength="20000" ${f.required?'required':''}>${esc(v)}</textarea>`;else if(f.type==='select')control=`<select id="f-${f.key}" name="${f.key}">${f.key==='accountId'?accountOpts(v):opts(f.options,v)}</select>`;else control=`<input id="f-${f.key}" name="${f.key}" type="${f.type??'text'}" value="${esc(v)}" ${f.required?'required':''} ${f.attrs??''} maxlength="${f.max??1000}">`;return `<div class="field${full}"><label for="f-${f.key}">${esc(f.label)}</label>${control}${f.hint?`<small>${esc(f.hint)}</small>`:''}</div>`;}
