function renderBrief(){
 const a=acc(u.brief);if(!a){closeBrief();return;}const dialog=$('#brief'),scroll=dialog.scrollTop;
 const hist=d.contacts.filter(c=>c.accountId===a.id).sort((a,b)=>b.date.localeCompare(a.date)),pending=actions(d).filter(x=>x.accountId===a.id);
 const detail=(label,value,full=false)=>`<div class="${full?'full':''}"><label>${label}</label><p>${esc(value||'To confirm')}</p></div>`;
 dialog.innerHTML=`<header class="dialog-head"><div><h2 id="brief-title">${esc(a.name)}</h2><p>${esc(a.city)} · ${a.province} · ${esc(a.type)}</p></div>${ib('close-brief','x','Close district brief')}</header><div class="brief-body"><div class="row" style="flex-wrap:wrap">${btn('contact','Log contact','message-square-plus',`data-id="${esc(a.id)}"`,'btn')}${btn('action','Next step','plus',`data-account="${esc(a.id)}"`)}${btn('account','Edit brief','pencil',`data-id="${esc(a.id)}"`)}</div><section><h3>Priorities & footprint</h3><div class="detail-grid">${detail('Desired customer outcome',a.goal,true)}${detail('Google',a.google)}${detail('Microsoft',a.microsoft)}${detail('Other tools / integrations',a.tools,true)}${detail('Students',a.students?Number(a.students).toLocaleString():'')}${detail('Staff',a.staff?Number(a.staff).toLocaleString():'')}${detail('Devices',a.devices?Number(a.devices).toLocaleString():'')}${detail('Renewal date',a.renewal?fmt(a.renewal,true):'')}${detail('Last meaningful contact',lastContact(d,a.id)?fmt(lastContact(d,a.id).date):'Not recorded')}${detail('Last visit',lastContact(d,a.id,true)?fmt(lastContact(d,a.id,true).date):'Not recorded')}${detail('Contact cadence',a.cadence+' days · editable per district')}${detail('Relationship',labels[status(d,a.id)])}${a.notes?detail('Notes',a.notes,true):''}</div></section><div class="source"><div class="between">${badge(a.evidence||'To confirm','teal')}<span>Checked ${fmt(a.checked,true)}</span></div><p>${esc(a.sourceNote||'Verify the technology footprint and commercial details.')}</p>${safeURL(a.sourceUrl)?`<a href="${esc(safeURL(a.sourceUrl))}" target="_blank" rel="noopener noreferrer">Open source</a>`:''}<p>Reference pin: approximate location, not a verified office unless you have checked and updated it.</p></div><section><div class="between"><h3>Next steps</h3>${ib('action','plus','Add next step',`data-account="${esc(a.id)}"`)}</div>${pending.map(t=>`<div class="brief-task"><button class="check" data-do="complete" data-id="${esc(t.id)}" aria-label="Complete ${esc(t.title)}">${ico('check')}</button><div class="grow"><strong>${esc(t.title)}</strong><small>${esc(t.channel)} · ${due(t.due)}</small></div>${ib('action','pencil','Edit next step',`data-id="${esc(t.id)}"`)}</div>`).join('')||'<p class="empty-inline">Agree on a useful next step and a date.</p>'}</section><section><div class="between"><h3>Stakeholders</h3>${ib('stakeholder','user-plus','Add stakeholder',`data-id="${esc(a.id)}"`)}</div>${a.stakeholders.map(s=>`<div class="stakeholder"><div><strong>${esc(s.name)}</strong><p>${esc(s.role)}</p>${s.email?`<p>${esc(s.email)}</p>`:''}${s.phone?`<p>${esc(s.phone)}</p>`:''}${s.notes?`<p>${esc(s.notes)}</p>`:''}</div>${ib('delete-stakeholder','x','Remove stakeholder',`data-id="${esc(s.id)}" data-account="${esc(a.id)}"`)}</div>`).join('')||'<p class="empty-inline">Map leadership, curriculum, IT, privacy, finance, educators and partner relationships.</p>'}</section><section><h3>Contact history</h3>${hist.map(c=>`<div class="contact-entry"><div class="channel">${ico(chIcons[c.channel])}</div><div class="grow"><h4>${esc(c.person||c.role||'District conversation')}</h4><p>${esc(c.notes)}</p>${c.outcome?`<p style="margin-top:7px"><strong>Outcome:</strong> ${esc(c.outcome)}</p>`:''}<small>${esc(c.channel)} · ${fmt(c.date,true)}${c.isDemo?' · Sample activity':''}</small></div>${ib('delete','trash-2','Delete contact entry',`data-type="contacts" data-id="${esc(c.id)}"`,'danger')}</div>`).join('')||'<p class="empty-inline">Log your first conversation with this district.</p>'}</section><div class="row" style="flex-wrap:wrap">${btn('add-to-trip','Add to itinerary','route',`data-id="${esc(a.id)}"`)}${btn('opportunity','Create opportunity','target',`data-account="${esc(a.id)}"`)}</div><div class="between"><p class="note">Your district record, ready to verify and develop.</p>${ib('delete','trash-2','Delete district',`data-type="accounts" data-id="${esc(a.id)}"`,'danger')}</div></div>`;
 if(!dialog.open)dialog.showModal();dialog.scrollTop=scroll;icons();
}
async function boundarySources(){
 try{const manifest=await readBoundaryManifest();modal('School-board boundary layers','Public geographic references · '+manifest.retrievedOn,`<div class="callout">${ico('map')}<span>Basemap: OpenStreetMap. Boundary polygons: government services, downloaded as a dated GeoJSON snapshot. Workspace notes and contacts are stored separately.</span></div><div class="boundary-sources-list">${manifest.sources.map(s=>`<div><a href="${esc(safeURL(s.catalogue))}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a><p class="boundary-source-meta">${esc(s.vintage)} · ${s.authorityCount} authority references</p></div>`).join('')}</div><h3>Coverage and limitations</h3><ul class="boundary-coverage">${manifest.coverageNotes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`,'');}catch{toast('Boundary source details could not load. Try reloading.');}
}
function closeBrief(){u.brief=null;if($('#brief').open)$('#brief').close();}
function confirm(title,text,fn,label='Confirm'){confirmFn=fn;modal(title,'',`<p style="font-size:.88rem;line-height:1.75">${esc(text)}</p>`,label,'confirm');}
function settings(){modal('Your workspace','Version 0.1 · portable, browser-local records',`<div class="callout">${ico('hard-drive')}<span>Your records are saved in this browser on this device. They are not uploaded to GitHub, synced to another device, or connected to Google CRM or Calendar.</span></div><section class="setting"><div><h3>Export a backup</h3><p>Download district briefs, contacts, next steps, opportunities, resources and itineraries.</p></div>${btn('export','Export backup','download')}</section><section class="setting"><div><h3>Restore a backup</h3><p>Review the record counts before replacing this browser’s workspace with a Westward JSON backup.</p></div>${btn('import','Import backup','upload')}</section><section class="setting"><div><h3>${d.mode==='demo'?'Make it yours':'Your starter directory'}</h3><p>${d.mode==='demo'?'Remove sample activity and assignments. Keep your own additions and the district directory.':'Selected authorities across four provinces. Add districts as you learn your assigned book.'}</p></div>${d.mode==='demo'?btn('start','Start my workspace','sparkles'):btn('account','Add district','plus')}</section><p class="note" style="margin-top:18px">The app code and sample references may be public. Your records remain local; browser storage is not a company CRM or a secure shared database. Map tiles and fonts load from external providers.</p>`,'');}
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}

document.addEventListener('click',event=>{
 const b=event.target.closest('[data-do]');if(!b)return;const {do:action,id,value}=b.dataset;
 try{switch(action){
 case 'nav':go(value);break;
 case 'menu':$('.sidebar').classList.toggle('open');break;
 case 'province':u.province=value;mapPosition=null;if(!filtered().some(a=>a.id===u.selected))u.selected=filtered()[0]?.id??'';render();break;
 case 'brief':if(!acc(id))return;u.brief=id;u.selected=id;renderBrief();break;
 case 'close-brief':closeBrief();break;
 case 'select':u.selected=id;map?.setView([acc(id).lat,acc(id).lng],Math.max(map.getZoom(),7));$('#directory-list').innerHTML=directory();icons();break;
 case 'contact':form('contact','',id,b.dataset.task);break;
 case 'action':case 'account':case 'trip':case 'opportunity':case 'resource':form(action,id,b.dataset.account);break;
 case 'stakeholder':form('stakeholder','',id);break;
 case 'complete':commit(n=>{const a=n.actions.find(x=>x.id===id);a.done=!a.done;},'Next step updated.');break;
 case 'all-actions':u.actionScope='open';go('visits');break;
 case 'action-scope':u.actionScope=value;render();break;
 case 'metric':if(value==='reviews')go('opportunities');else{u.actionScope=value==='due'?'due':'visits';go('visits');}break;
 case 'planner':go('planner');break;
 case 'select-trip':u.trip=id;render();break;
 case 'add-stop':{const stop=$('#stop-select').value,t=trip();if(!stop)return toast('Choose a district first.');if(t.accountIds.includes(stop))return toast('That district is already on the route.');if(t.accountIds.length>=9)return toast('Use up to 9 district stops per itinerary.');commit(n=>{const item=n.trips.find(x=>x.id===t.id);item.accountIds.push(stop);item.isDemo=false;},'Stop added.');break;}
 case 'remove-stop':{const t=trip();commit(n=>{const item=n.trips.find(x=>x.id===t.id);item.accountIds=item.accountIds.filter(x=>x!==id);item.isDemo=false;},'Stop removed.');break;}
 case 'move-stop':{const t=trip(),i=+b.dataset.index,j=i+(+b.dataset.direction);if(j<0||j>=t.accountIds.length)return;commit(n=>{const item=n.trips.find(x=>x.id===t.id);[item.accountIds[i],item.accountIds[j]]=[item.accountIds[j],item.accountIds[i]];item.isDemo=false;},'Route order updated.');break;}
 case 'calendar':{const t=trip();if(t){download('Westward-Itinerary-'+t.date+'.ics',calendar(t,d),'text/calendar');toast('Proposed all-day itinerary exported.');}break;}
 case 'route-map':{u.province='all';u.status='all';mapPosition=null;const t=trip();go('territory');if(t&&map)map.fitBounds(L.latLngBounds(tripPoints(t,d).map(p=>[p.lat,p.lng])),{padding:[55,55]});break;}
 case 'add-to-trip':if(!d.trips.length){closeBrief();go('planner');form('trip');toast('Create an itinerary, then add this district.');}else{u.form={kind:'add-to-trip',context:id};modal('Add to itinerary',acc(id).name,field(F('tripId','Itinerary','select',{options:d.trips.map(t=>[t.id,t.name+' · '+fmt(t.date)])}),u.trip),'Add district','add-to-trip');}break;
 case 'delete':{const type=b.dataset.type;if(!['accounts','actions','contacts','trips','opportunities','resources'].includes(type))return;confirm('Remove this '+({accounts:'district',actions:'next step',contacts:'contact entry',trips:'itinerary',opportunities:'opportunity',resources:'resource'}[type])+'?',type==='accounts'?'This also removes its contacts, next steps and opportunities, and removes it from itineraries.':'This removes the selected record from your workspace.',()=>{if(type==='accounts'&&u.brief===id)closeBrief();commit(n=>{n[type]=n[type].filter(x=>x.id!==id);if(type==='accounts'){for(const k of ['contacts','actions','opportunities'])n[k]=n[k].filter(x=>x.accountId!==id);n.trips.forEach(t=>t.accountIds=t.accountIds.filter(x=>x!==id));}},'Record removed.');},'Remove');break;}
 case 'delete-stakeholder':confirm('Remove this stakeholder?','Only the stakeholder-list entry will be removed.',()=>commit(n=>{const a=n.accounts.find(x=>x.id===b.dataset.account);a.stakeholders=a.stakeholders.filter(s=>s.id!==id);},'Stakeholder removed.'),'Remove stakeholder');break;
 case 'settings':settings();break;
 case 'export':download('Westward-Backup-'+today()+'.json',JSON.stringify(d,null,2),'application/json');toast('Workspace backup downloaded.');break;
 case 'import':$('#restore').click();break;
 case 'start':confirm('Ready to make it yours?','This removes sample activity and sample account assignments. Your own additions and the starter district directory remain.',()=>{const next=clearDemo(d);commit(n=>Object.assign(n,next),'Your workspace is ready. Start with your account book.');},'Start my workspace');break;
 case 'close-editor':$('#editor').close();break;
 }}catch(err){toast(err.message);}
});

document.addEventListener('submit',event=>{
 if(event.target.id!=='entry-form')return;event.preventDefault();const formEl=event.target,v=Object.fromEntries(new FormData(formEl)),kind=formEl.dataset.kind;
 try{
 if(kind==='confirm'){const fn=confirmFn;$('#editor').close();fn?.();return;}
 const cfg=u.form,record={};for(const f of cfg.fields??[]){if(f.type==='section')continue;record[f.key]=f.type==='checkbox'?!!v[f.key]:String(v[f.key]??'').trim();}
 if(kind==='account'){record.lat=+record.lat;record.lng=+record.lng;record.cadence=+record.cadence;if(record.sourceUrl&&!safeURL(record.sourceUrl))throw Error('Use an http or https source link.');}
 if(kind==='resource'){if(!safeURL(record.url))throw Error('Use a full http or https link.');record.url=safeURL(record.url);}
 if(kind==='contact'&&record.nextTitle&&!record.nextDate)throw Error('Choose a follow-up date.');
 const newId=cfg.id||uid();
 commit(n=>{
  if(kind==='stakeholder'){n.accounts.find(a=>a.id===cfg.context).stakeholders.push({...record,id:newId});return;}
  if(kind==='add-to-trip'){const t=n.trips.find(t=>t.id===v.tripId);if(!t)throw Error('Choose an itinerary.');if(t.accountIds.includes(cfg.context))throw Error('This district is already on the itinerary.');if(t.accountIds.length>=9)throw Error('Use up to 9 stops.');t.accountIds.push(cfg.context);t.isDemo=false;return;}
  if(kind==='contact'){const {nextTitle,nextDate,nextChannel,completeTask,...contact}=record;n.contacts.push({...contact,id:newId,isDemo:false});if(nextTitle)n.actions.push({id:uid(),accountId:contact.accountId,title:nextTitle,due:nextDate,channel:nextChannel,priority:'Normal',owner:'Darren',notes:'',done:false,isDemo:false});const linked=n.actions.find(a=>a.id===cfg.taskId);if(linked&&completeTask&&linked.accountId===contact.accountId)linked.done=true;return;}
  const old=n[cfg.collection].find(r=>r.id===cfg.id);const row={...(old??{}),...record,id:newId,isDemo:false};
  if(kind==='action')row.done=old?.done??false;if(kind==='account'){row.stakeholders=old?.stakeholders??[];row.demoAssigned=false;}if(kind==='trip')row.accountIds=old?.accountIds??[];
  if(old)Object.assign(old,row);else n[cfg.collection].push(row);
 },kind==='contact'?'Contact saved. Your next step is on the list.':'Saved to your workspace.');
 $('#editor').close();if(kind==='trip'){u.trip=newId;go('planner');}if(kind==='account')u.selected=newId;
 }catch(err){$('.form-error',formEl).textContent=err.message;}
});

document.addEventListener('change',event=>{
 const el=event.target;if(el.id==='map-status'){u.status=el.value;mapPosition=null;render();}if(el.id==='account-scope'){u.scope=el.value;render();}if(el.id==='resource-category'){u.category=el.value;render();}
 if(el.dataset.stage)commit(n=>{const o=n.opportunities.find(o=>o.id===el.dataset.stage);o.stage=el.value;o.isDemo=false;},'Opportunity stage updated.');
});
document.addEventListener('input',event=>{
 const el=event.target;if(el.id==='list-search'){u.query=el.value;const pos=el.selectionStart;render();const input=$('#list-search');input.focus();input.setSelectionRange(pos,pos);}
 if(el.id==='global-search'){const q=el.value.trim().toLowerCase();if(!q){$('#results').innerHTML='';return;}const matches=d.accounts.filter(a=>[a.name,a.city,a.province].some(v=>v.toLowerCase().includes(q))).slice(0,8);$('#results').innerHTML=`<div class="search-results">${matches.map(a=>`<button class="search-result" data-do="brief" data-id="${esc(a.id)}"><strong>${esc(a.name)}</strong><small>${a.province} · ${esc(a.city)}</small></button>`).join('')||'<div class="empty-inline">No matching district.</div>'}</div>`;}
});
document.addEventListener('click',event=>{if(!event.target.closest('.search')){const box=$('#results');if(box)box.innerHTML='';}if($('.sidebar.open')&&!event.target.closest('.sidebar')&&!event.target.closest('[data-do=menu]'))$('.sidebar').classList.remove('open');});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('.sidebar')?.classList.remove('open');if($('#results'))$('#results').innerHTML='';}});
$('#brief').addEventListener('close',()=>u.brief=null);
$('#restore').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Use a Westward JSON backup under 10 MB.');const next=validate(JSON.parse(await file.text()));confirm('Restore this workspace?',`${next.accounts.length} districts, ${next.contacts.length} contacts, ${next.actions.length} next steps and ${next.trips.length} itineraries. This replaces the workspace in this browser. Export your existing backup first if needed.`,()=>{closeBrief();commit(n=>Object.assign(n,next),'Workspace restored.');u.trip=next.trips[0]?.id??'';u.selected=next.accounts[0]?.id??'';},'Restore workspace');}catch(err){toast('Import failed: '+err.message);}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(nav.some(x=>x[0]===v)&&v!==u.view){u.view=v;u.query='';render();}});
window.addEventListener('storage',event=>{if(event.key===KEY){storageOK=false;loadWarning='This workspace changed in another tab. Export any unsaved work, then reload before editing.';render();}});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',render,{once:true});else render();
